mapper.update:
update dm_alarm_event set recover_time = #{recoverTime}, update_time = current_timestamp
where dedup_key = #{dedupKey} and is_deleted = 0 and recover_time is null
  and last_trigger_time <= #{recoverTime}

mapper.select:
select id as interface_id, task_id, interface_name, host, port,
       transfer_type, transfer_protocol, protocol_config_id
from collect_interface_config where id = #{id}
